"use client";
import { useState } from "react";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { useDroppable } from "@dnd-kit/core";
import { Plus, X, AlignLeft, Sparkles } from "lucide-react";
import TaskItem from "./TaskItem";

export default function ScrumColumn({ id, title, items, setColumns, activeSprint }: any) {
  const [showForm, setShowForm] = useState(false);
  const [input, setInput] = useState("");
  const { setNodeRef } = useDroppable({ id });

  const addTask = async () => {
    if (!input.trim()) return;
    const res = await fetch("/api/scrumboard/items", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: input, columnId: id, sprint: activeSprint }),
    });
    if (res.ok) {
      const newItem = await res.json();
      setColumns((prev: any) => ({ ...prev, [id]: [...prev[id], newItem.title] }));
      setInput(""); setShowForm(false);
    }
  };

  return (
    <div ref={setNodeRef} className="bg-[#14161F]/40 backdrop-blur-sm p-4 rounded-2xl w-[260px] border border-white/5 flex flex-col gap-4 h-[calc(100vh-140px)] flex-shrink-0 shadow-inner">
      <div className="flex justify-between items-center px-1">
        <div className="flex items-center gap-2">
          <div className={`w-1.5 h-4 rounded-full ${id === 'done' ? 'bg-green-500' : 'bg-blue-500'}`} />
          <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">{title}</h2>
        </div>
        <span className="text-[10px] text-slate-600 font-mono">[{items?.length || 0}]</span>
      </div>

      <div className="flex-1 overflow-y-auto pr-1 custom-scrollbar flex flex-col gap-3">
        <SortableContext items={items || []} strategy={verticalListSortingStrategy}>
          {items?.map((item: string) => <TaskItem key={item} id={item} text={item} />)}
        </SortableContext>
      </div>
      
      <button 
        onClick={() => setShowForm(true)} 
        className="flex items-center justify-center gap-2 py-2.5 rounded-xl text-slate-500 hover:text-white hover:bg-white/5 transition-all duration-200 font-medium text-xs border border-transparent hover:border-white/10"
      >
        <Plus size={14} /> Nieuwe taak
      </button>
      
      {/* MODERN FORM MODAL */}
      {showForm && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-md p-4 overflow-hidden">
          <div className="bg-[#1C1F2B] w-full max-w-lg rounded-[2rem] border border-white/10 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-blue-500/10 rounded-lg text-blue-500">
                    <Sparkles size={18} />
                  </div>
                  <div>
                    <h3 className="text-white font-bold text-lg leading-none">Nieuwe Taak</h3>
                    <p className="text-slate-500 text-[11px] mt-1 uppercase tracking-widest">{activeSprint} • {title}</p>
                  </div>
                </div>
                <button onClick={() => setShowForm(false)} className="w-8 h-8 flex items-center justify-center rounded-full bg-white/5 text-slate-400 hover:text-white transition-colors">
                  <X size={18} />
                </button>
              </div>

              <div className="space-y-4">
                <div className="relative">
                  <AlignLeft className="absolute left-4 top-4 text-slate-600" size={16} />
                  <textarea 
                    className="w-full p-4 pl-12 bg-black/20 border border-white/5 rounded-2xl text-white outline-none focus:border-blue-500/50 focus:ring-4 focus:ring-blue-500/5 transition-all min-h-[160px] resize-none text-sm placeholder:text-slate-700 shadow-inner" 
                    placeholder="Wat moet er gebeuren?"
                    value={input} onChange={e => setInput(e.target.value)} autoFocus 
                  />
                </div>
              </div>

              <div className="flex gap-3 mt-8">
                <button 
                  onClick={() => setShowForm(false)} 
                  className="flex-1 py-3 rounded-xl text-slate-400 font-bold text-xs hover:bg-white/5 transition-all border border-transparent hover:border-white/5"
                >
                  Annuleren
                </button>
                <button 
                  onClick={addTask} 
                  className="flex-[2] bg-gradient-to-r from-blue-600 to-indigo-600 py-3 rounded-xl text-white font-bold text-xs hover:opacity-90 shadow-lg shadow-blue-600/20 active:scale-[0.98] transition-all"
                >
                  Taak Opslaan
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}